import{_ as r,o as i,c as s,a3 as t,j as e,a as d}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/grundschule/tutorials-gs-zeugnistutorial-explorer.png",u="/bilder/grundschule/tutorials-gs-zeugnistutorial-konfigurationsdatei-beispiel.png",l="/bilder/grundschule/tutorials-gs-zeugnistutorial-konfigurationsdatei-beispiel2.png",z=JSON.parse('{"title":"Das Erscheinungsbild von Grundschulzeugnissen konfigurieren","description":"","frontmatter":{"title":"Das Erscheinungsbild von Grundschulzeugnissen konfigurieren","pageClass":"zeugnisoptionen","source_pageid":1247,"source_revision":6798},"headers":[],"relativePath":"zeugnisse/grundschule/grundschulzeugnisse-konfiguration-des-erscheinungsbildes-von-zeugnissen-tutorial.md","filePath":"zeugnisse/grundschule/grundschulzeugnisse-konfiguration-des-erscheinungsbildes-von-zeugnissen-tutorial.md"}'),g={name:"zeugnisse/grundschule/grundschulzeugnisse-konfiguration-des-erscheinungsbildes-von-zeugnissen-tutorial.md"};function o(h,n,m,c,f,b){return i(),s("div",null,[...n[0]||(n[0]=[t('<h1 id="das-erscheinungsbild-von-grundschulzeugnissen-konfigurieren" tabindex="-1">Das Erscheinungsbild von Grundschulzeugnissen konfigurieren <a class="header-anchor" href="#das-erscheinungsbild-von-grundschulzeugnissen-konfigurieren" aria-label="Permalink to &quot;Das Erscheinungsbild von Grundschulzeugnissen konfigurieren&quot;">​</a></h1><p>Passen Sie die mitgelieferte INI-Datei an den verwendeten Zeugnistyp an. Die Anleitung beschreibt Fächerfolge, Layout, Inhalte, Überschriften und Unterschriften.</p><p>Nehmen Sie bitte die <a href="/reporting/zeugnisformulare/zeugnisse-themenuebersicht.html">Themenseiten zu den Zeugnissen</a> zur Kenntnis, wie Zeugnisse zu installieren und über die <em>Zeugniseinstellungen.ini</em> konfiguriert werden <em>könnten</em>.</p><p>Bezüglich für die Grundschulzeugnisse ist dieses Tutorial hier eine verkürzte, spezialisierte Übersicht.</p><h2 id="der-speicherort-der-dateien" tabindex="-1">Der Speicherort der Dateien <a class="header-anchor" href="#der-speicherort-der-dateien" aria-label="Permalink to &quot;Der Speicherort der Dateien&quot;">​</a></h2><p><a href="/bilder/grundschule/tutorials-gs-zeugnistutorial-explorer.png"><img src="'+a+'" alt="Die Übersicht im Windows-Explorer. Hier ist relevant: Wir sind bei den SchILD-Reports im Verzeichnis, das für Zeugnisse angelegt wurde. Es ist die Konfigurationsdatei zu sehen, ebenfalls ein PDF, in dem die Einstellungen noch einmal erklärt werden. Weiterhin die RTM-Dateien, welche die eigentlichen Zeugnisreports darstellen." loading="lazy"></a></p><p><em>Die Übersicht im Windows-Explorer. Hier ist relevant: Wir sind bei den SchILD-Reports im Verzeichnis, das für Zeugnisse angelegt wurde. Es ist die Konfigurationsdatei zu sehen, ebenfalls ein PDF, in dem die Einstellungen noch einmal erklärt werden. Weiterhin die RTM-Dateien, welche die eigentlichen Zeugnisreports darstellen.</em></p><p>Die installierten Zeugnisformulare lassen sich in ihrem Erscheinungsbild über eine Konfigurationsdatei einstellen. Diese Datei wird mit einem Zeugnispaket mit heruntergeladen und ist somit enthalten.</p><p>Bei den <strong>Ankreuzzeugnissen</strong> heißt die Datei <em>AnkreuzzeugnisEinstellungen.ini</em>. Hierbei kann es sein, dass die Dateiendung <em>&quot;.ini&quot;</em> von Windows ausgeblendet wird und die Datei somit lediglich als <em>AnkreuzzeugnisEinstellungen</em> angezeigt wird.</p><p>Für die <strong>normalen Zeugnisse</strong> nutzen Sie die <em>Zeugniseinstellungen.ini</em>, die bei den jeweiligen Zeugnissen mitgeliefert wird. Für die <strong>Hybridzeugnisse</strong> heißt die Datei entsprechend <em>HybridzeugnisEinstellungen.ini</em>.</p><p>Die Datei lässt sich <strong>Bearbeiten</strong>, indem Sie im Windows-Explorer oder direkt aus dem Report-Explorer in ScHILD-NRW <code>doppelt angeklickt</code> wird.</p><p>Bearbeiten Sie die Datei gewünscht und <code>speichern</code> Sie die gemachten Einstellungen.</p><p>Generieren Sie anschließend einen Zeugnis-Report, holt sich der Report die Einstellungen automatisch aus der zugehörigen Konfigurationsdatei.</p><h2 id="aufbau-der-konfigurationsdatei" tabindex="-1">Aufbau der Konfigurationsdatei <a class="header-anchor" href="#aufbau-der-konfigurationsdatei" aria-label="Permalink to &quot;Aufbau der Konfigurationsdatei&quot;">​</a></h2><p>Die Zeugnisdatei ist wie folgt aufgebaut:</p><ul><li>Zeilen, die mit einem <em>Semikolon (;)</em> beginnen sind für Menschen zu lesende Kommentare und werden vom Zeugnisformular</li></ul><p>bei der Verarbeitung ignoriert.</p><ul><li>Zusammengehörige Konfigurationen werden in Blöcken zusammengefasst, die mit eckigen Klammern umgeben sind.</li></ul><p><a href="/bilder/grundschule/tutorials-gs-zeugnistutorial-konfigurationsdatei-beispiel.png"><img src="'+u+'" alt="Die Eintragungen, wie sie in der Konfigurationsdatei erscheinen. Die Zeilen mit Semikolon sind Kommentare für den Menschen und werden beim Zeugnisdruck nicht durch den Computer verarbeitet." loading="lazy"></a></p><p><em>Die Eintragungen, wie sie in der Konfigurationsdatei erscheinen. Die Zeilen mit Semikolon sind Kommentare für den Menschen und werden beim Zeugnisdruck nicht durch den Computer verarbeitet.</em></p><p>Für eine andere Reihenfolge der Fächer im linken Notenblock ändern Sie zum Beispiel</p><blockquote><p>[Notenzeugnisreihenfolge_Links]</p><p>Deutsch</p><p>Sprache</p><p>Sachunterricht</p><p>Mathematik</p></blockquote><p>zu der gewünschten Reihenfolge verändern</p><blockquote><p>[Notenzeugnisreihenfolge_Links]</p><p>Deutsch</p><p>Mathematik</p><p>Sprache</p><p>Sachunterricht</p></blockquote><p><a href="/bilder/grundschule/tutorials-gs-zeugnistutorial-konfigurationsdatei-beispiel2.png"><img src="'+l+'" alt="Das Semikolon (blau) zeigt an, dass es sich um einen Kommentar handelt, der vom Computer ignoriert wird. Der grüne Bereich im Kommentar teilt uns mit, welche Werte zulässig als Jahrgänge eingetragen werden können. Weiterhin ist zum Beispiel zu sehen, dass manche Felder gesteuert werden, indem etwa ein Semikolon entfernt wird: zum Beispiel wird ASVAusblenden angewendet, wenn das Semikolon entfernt wurde." loading="lazy"></a></p><p><em>Das Semikolon (blau) zeigt an, dass es sich um einen Kommentar handelt, der vom Computer ignoriert wird. Der grüne Bereich im Kommentar teilt uns mit, welche Werte zulässig als Jahrgänge eingetragen werden können. Weiterhin ist zum Beispiel zu sehen, dass manche Felder gesteuert werden, indem etwa ein Semikolon entfernt wird: zum Beispiel wird ASVAusblenden angewendet, wenn das Semikolon entfernt wurde.</em></p><p>Soll verändert werden, ab welchem Jahrgang <em>Noten</em> gegeben werden, wäre die Zeile</p><blockquote><p>NotenAbJahrgang=03</p></blockquote><p>so zu verändern, dass statt <em>03</em> eben <em>E1</em>, <em>E2</em> oder <em>04</em> steht.</p><p>Hier ist zu sehen, dass die zur Eintragung zulässigen Werte immer in den Kommentaren direkt bei der Zeile stehen.</p>',30),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),d("Hinweis")]),e("p",null,"Beachten Sie, dass Änderungen, die in einem Jahr vorgenommen werden, auch in allen Folgejahren in der dann neuen mit den Zeugnissen ausgelieferten Konfigurationsdatei erneut einzutragen sind."),e("p",null,"Die meisten Optionen können Sie auf ihren Standardwerten belassen. Passen Sie gezielt die Angaben Ihrer Schule an, etwa die Namen der unterzeichnenden Personen in Abschnitt 5. Ändern Sie weitere Optionen nur, wenn das gewünschte Zeugnislayout dies erfordert.")],-1),t('<h2 id="inhalte-der-datei-und-felder-zur-konfiguration" tabindex="-1">Inhalte der Datei und Felder zur Konfiguration <a class="header-anchor" href="#inhalte-der-datei-und-felder-zur-konfiguration" aria-label="Permalink to &quot;Inhalte der Datei und Felder zur Konfiguration&quot;">​</a></h2><p>In der Datei werden folgende Aspekte konfiguriert. Wird ein Feld über ein Semikolon ein- oder ausgeschaltet, ist das Semikolon hier in diesem Artikel wie in der Datei als Standard entweder <em>gesetzt</em> oder <em>entfernt</em>.</p><h3 id="_1-facherreihenfolge-festlegen" tabindex="-1">1. Fächerreihenfolge festlegen <a class="header-anchor" href="#_1-facherreihenfolge-festlegen" aria-label="Permalink to &quot;1. Fächerreihenfolge festlegen&quot;">​</a></h3><p>Wie im Beispiel oben gezeigt werden die Bezeichnungen der Fächer <em>exakt so geschrieben wie in der Datei vorgefunden</em> in die gewünschte Reihenfolge gebracht.</p><h3 id="_2-das-allgemeine-layout-festlegen" tabindex="-1">2. Das allgemeine Layout festlegen <a class="header-anchor" href="#_2-das-allgemeine-layout-festlegen" aria-label="Permalink to &quot;2. Das allgemeine Layout festlegen&quot;">​</a></h3><p>Über die hier aufgeführten Schalter wird das allgemeine Layout mit Schrift, Druck und Seitenumbrüchen gesteuert.</p><table tabindex="0"><thead><tr><th>Steuerbefehl</th><th>Erklärung</th></tr></thead><tbody><tr><td><strong>;Duplex=Vertikal</strong></td><td>aktiviert automatisch den doppelseitigen Druck durch Entfernen des Semikolons (<strong>;</strong>)</td></tr><tr><td><strong>Blocksatz</strong></td><td>Blocksatzdruck wird deaktiviert, wenn ein Semikolon gesetzt wird.</td></tr><tr><td><strong>SchriftgroesseBemerkungen</strong>=10</td><td>steuert die Schriftgröße. Als Standard ist <em>10</em> gesetzt. Stellen Sie eine Schriftgröße &quot;ähnlich groß wie 10&quot; ein, um kleiner oder größer zu drucken.</td></tr><tr><td><strong>;ASVSeite2</strong></td><td>setzt das Arbeits- und Sozialverhalten erst auf die zweite Seite, wenn hier das Semikolon entfernt wird.</td></tr><tr><td><strong>;FächerAufNeuerSeite</strong></td><td>steuert, ob die Fächer auf einer neue Seite begonnen werden. Steht das Semikolon, ist dieses Verhalten deaktiviert und die Fächer werden direkt auf der ersten Seite gedruckt.</td></tr><tr><td><strong>BemerkungenAufNeuerSeite</strong>=E1;E2;E3;03;04</td><td><em>BemerkungenAufNeuerSeite</em> steuert, vor welchen Jahrgängen ein Seitenumbruch für die Zeugnis- und Versetzungsbemerkungen erzeugt wird. Die Jahrgänge, <em>für die dies zutreffen soll</em>, folgen durch ein Semikolon aus Aufzählungszeichen getrennt.</td></tr></tbody></table><h3 id="_3-allgemeine-inhaltliche-einstellungen" tabindex="-1">3. Allgemeine inhaltliche Einstellungen <a class="header-anchor" href="#_3-allgemeine-inhaltliche-einstellungen" aria-label="Permalink to &quot;3. Allgemeine inhaltliche Einstellungen&quot;">​</a></h3><p>Hier werden generelle Einstellungen zu Inhalten vorgenommen.</p><table tabindex="0"><thead><tr><th>Steuerbefehl</th><th>Erklärung</th></tr></thead><tbody><tr><td><strong>NotenAbJahrgang</strong>=03</td><td>NotenAbJahrgang lässt den Jahrgang setzen, <em>ab</em> dem Noten auf Zeugnissen gedruckt werden. Zulässige Start-Jahrgänge sind <em>E1, E2, 03</em> und <em>04</em></td></tr><tr><td><strong>;MitJahrgang</strong></td><td>wenn das Semikolon gesetzt ist, werden nur die Klassen im Zeugniskopf gedruckt. Wird das Semikolon entfernt, werden Klasse und Jahrgang ausgegeben. Diese Einstellung ist nur für die Jahrgänge <em>03</em> und <em>04</em> relevant.</td></tr><tr><td><strong>;DeutschNotenEinzeln</strong></td><td>Noten für Lesen, Rechtschreibung und Sprachgebrauch direkt unter entsprechenden Kompetenzbeschreibungen <strong>oder</strong> gebündelt nach den Kompetenzen ausgeben. Für den letzteren Fall ist das Semikolon zu setzen.</td></tr><tr><td><strong>;NachnameInVersetzungsvermerk</strong></td><td>Das Semikolon ist zu entfernen, um Nachnamen des Kindes im Versetzungstext auszugeben.</td></tr><tr><td><strong>NurRufname</strong></td><td>Falls in SchILD-NRW ein Eintrag unter &quot;alle Namen&quot; vorhanden ist, diese aber nicht auf das Zeugnis gedruckt sollen, ist kein Semikolon zu setzen.</td></tr><tr><td><strong>;ASVAusblenden</strong></td><td>Arbeits und Sozialverhalten nicht auf dem Zeugnis drucken: Entfernen Sie das Semikolon.</td></tr></tbody></table><h3 id="_4-layout-fur-facher-und-kompetenzen-festlegen" tabindex="-1">4. Layout für Fächer und Kompetenzen festlegen <a class="header-anchor" href="#_4-layout-fur-facher-und-kompetenzen-festlegen" aria-label="Permalink to &quot;4. Layout für Fächer und Kompetenzen festlegen&quot;">​</a></h3><p>Über diese Schalter werden Layoutfunktionen wie Zeilenabstände, Fächerposition, Linien zwischen Kompetenzen oder das verwendete Ankreuzsymbol gesteuert.-</p><table tabindex="0"><thead><tr><th>Steuerbefehl</th><th>Erklärung</th></tr></thead><tbody><tr><td><strong>;Linien</strong></td><td>Durch Weglassen des Semikolons werden Linien hinzugefügt</td></tr><tr><td><strong>Vorname</strong></td><td>Vorname des Kindes bei jedem Fach mit ausgeben, zum Deaktivieren der Linien ist das Semikolon setzen</td></tr><tr><td><strong>AbstandFaecher</strong>=3</td><td>Setzt den Abstand zwischen den Fächern</td></tr><tr><td><strong>;AbstandZuBemerkungen</strong>=10</td><td>Setzt den Abstand zu den Bemerkungen</td></tr><tr><td><strong>KopfHoehe</strong>=28</td><td>Dieses Feld setzt die Breite der Fachkopfes in mm. Diese hängt auch von der Zahl gewählter Kompetenzstufen ab (immer, teilweise, überwiegend) und beeinflusst auch den Abstand zwischen Fach- und Kompetenzbeschreibung. Diese Einstellung wäre beim Wunsch auf individuelle Konfiguration durch Ausprobieren an das gewünschte Erscheinungsbild einzustellen.</td></tr><tr><td><strong>Zeilenhoehe</strong>=5</td><td>Höhe einer „Ankreuz-Zeile“ in mm. Erlaubte Werte sind <em>4</em> oder <em>5</em>.</td></tr><tr><td><strong>FachPosition</strong>=Mitte</td><td>Vertikale Position der Fächerbezeichnungen. Erlaubte Werte sind <em>Oben</em> und <em>Mitte</em>.</td></tr><tr><td><strong>;Zusammmenhalten</strong></td><td>Ist Fächer <em>zusammenhalten</em> per Auslassung des Semikolons aktiviert, werden innerhalb eines Faches keine Zeilenumbrüche erzeugt.</td></tr><tr><td><strong>;ZusammenhaltenE1</strong>=Deutsch(einzeln);Englisch;Mathematik</td><td>Sollen nur einzelne Fächer zusammengehalten werden, lässt sich dies jeweils für die benannten Jahrgänge für die Jahrgänge über diese Schalter erzeugen. Die Option (einzeln) gilt nur für das Fach Deutsch.</td></tr><tr><td><strong>;ZusammenhaltenE2</strong>=Deutsch(einzeln);Englisch;Mathematik</td><td>Sollen nur einzelne Fächer zusammengehalten werden, lässt sich dies jeweils für die benannten Jahrgänge für die Jahrgänge über diese Schalter erzeugen. Die Option (einzeln) gilt nur für das Fach Deutsch.</td></tr><tr><td><strong>;Zusammenhalten03</strong>=Deutsch(einzeln);Englisch;Mathematik</td><td>Sollen nur einzelne Fächer zusammengehalten werden, lässt sich dies jeweils für die benannten Jahrgänge für die Jahrgänge über diese Schalter erzeugen. Die Option (einzeln) gilt nur für das Fach Deutsch.</td></tr><tr><td><strong>;Zusammenhalten04</strong>=Deutsch(einzeln);Englisch;Mathematik</td><td>Sollen nur einzelne Fächer zusammengehalten werden, lässt sich dies jeweils für die benannten Jahrgänge für die Jahrgänge über diese Schalter erzeugen. Die Option (einzeln) gilt nur für das Fach Deutsch.</td></tr><tr><td><strong>Ankreuzsymbol</strong>=X</td><td>Hier wird das Symbol für Ankreuzkästchen gewählt. Der Wert <em>X</em> setzt ein &quot;X&quot;, <em>C</em> setzt einen Haken.</td></tr><tr><td><strong>LeereAnkreuzkompetenzen</strong>=Z</td><td>Legt die Sichtbarkeit von nicht gesetzten Ankreuzkompetenzen fest. Beim Wert <em>Z</em> (=Zeigen) werden nicht gesetzte Kompetenzen auf dem Zeugnis ausgegeben, beim Wert <em>D</em> (Durchgestrichen) erscheinen nicht gesetzte Kompetenzen durchgestrichen auf dem Zeugnis, beim Wert <em>A</em> (Ausblenden) werden nicht gesetzte Kompetenzen ausgeblendet.</td></tr><tr><td><strong>FachKopfSichtbarE1</strong>=SG;M;SP</td><td>Kompetenzstufen werden i.d.R. für jedes Fach mit gedruckt. Soll dies für bestimmte Jahrgänge genauer gesteuert werden, können hier die Fächer angegeben werden, für welche die Kompetenzstufen gedruckt werden. Wird die ganze Zeile per Semikolon deaktiviert, werden für alle Fächer Kompetenzstufen gedruckt.</td></tr><tr><td><strong>;FachKopfSichtbarE2</strong>=SG;M;SP</td><td>Kompetenzstufen werden i.d.R. für jedes Fach mit gedruckt. Soll dies für bestimmte Jahrgänge genauer gesteuert werden, können hier die Fächer angegeben werden, für welche die Kompetenzstufen gedruckt werden. Wird die ganze Zeile per Semikolon deaktiviert, werden für alle Fächer Kompetenzstufen gedruckt.</td></tr><tr><td><strong>;FachKopfSichtbar03</strong>=KR;RS;MU</td><td>Kompetenzstufen werden i.d.R. für jedes Fach mit gedruckt. Soll dies für bestimmte Jahrgänge genauer gesteuert werden, können hier die Fächer angegeben werden, für welche die Kompetenzstufen gedruckt werden. Wird die ganze Zeile per Semikolon deaktiviert, werden für alle Fächer Kompetenzstufen gedruckt.</td></tr><tr><td><strong>;FachKopfSichtbar04</strong>=D;E;M</td><td>Kompetenzstufen werden i.d.R. für jedes Fach mit gedruckt. Soll dies für bestimmte Jahrgänge genauer gesteuert werden, können hier die Fächer angegeben werden, für welche die Kompetenzstufen gedruckt werden. Wird die ganze Zeile per Semikolon deaktiviert, werden für alle Fächer Kompetenzstufen gedruckt.</td></tr></tbody></table><h3 id="_5-text-und-layout-der-unterschriften-anpassen" tabindex="-1">5. Text und Layout der Unterschriften anpassen <a class="header-anchor" href="#_5-text-und-layout-der-unterschriften-anpassen" aria-label="Permalink to &quot;5. Text und Layout der Unterschriften anpassen&quot;">​</a></h3><p>Über diese Schalter werden Art und Layout der Unterschriften gesteuert.</p><table tabindex="0"><thead><tr><th>Steuerbefehl</th><th>Erklärung</th></tr></thead><tbody><tr><td><strong>Unterschrift</strong>=VN</td><td>Über die unterschiedlichen Optionen wird die Art der Unterschriften eingestellt. Zulässige Schalter sind: <em>VN</em> = Vorname Nachname; <em>NV</em> = Nachname, Vorname; <em>N</em> = Nachname, KlassenlehrerIn; <em>ON</em> = Klassenleitung</td></tr><tr><td><strong>PositionSchulleitungText</strong>=R</td><td>Zulässige Optionen zur Positionierung der Schulleitungsunterschrift sind <em>R</em> für rechts und <em>L</em> für links.</td></tr><tr><td><strong>;SchulleitungText</strong>=Vertretung (Frau Mustermann)</td><td>Falls nicht die in SchILD hinterlegte Schulleitung unterschreibt, kann hier ein freier Text eingegeben werden, der unter der Linie zum unterschreiben gedruckt wird. Zusätzlich zur Angabe des freien Textes muss bei einem gewünschten Eintrag das Semikolon vor <code>;SchulleitungText=</code> entfernt werden.</td></tr><tr><td><strong>UnterschriftMitStVertr</strong>=nein</td><td>Ist die <em>Stellvertrende Klassenleitung</em> auch anzeigen? Optionen: <em>ja</em>, <em>nein</em>.</td></tr><tr><td><strong>;KlassenleitungText</strong>=Klassenleitung</td><td>Falls nicht die Klassenleitung aus SchILD-NRW unterschreiben soll, kann hier ein Text eingegeben werden.</td></tr><tr><td><strong>;SonderpaedagogeText</strong>=Herr Mustermann</td><td>Der Name der sonderpädagogischen Lehrkraft wird i.d.R. aus SchILD-NRW heraus generiert. Über diesen Schalter ein (freier) Name für die Unterschrift eingetragen werden.</td></tr></tbody></table><h3 id="_6-anpassen-von-uberschriften-und-textpassagen" tabindex="-1">6. Anpassen von Überschriften und Textpassagen <a class="header-anchor" href="#_6-anpassen-von-uberschriften-und-textpassagen" aria-label="Permalink to &quot;6. Anpassen von Überschriften und Textpassagen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Steuerbefehl</th><th>Erklärung</th></tr></thead><tbody><tr><td><strong>ASVText</strong>=Arbeitsverhalten</td><td>Hier lässt sich mit einem freien Text die Überschrift für das Arbeits- und Sozialverhalten setzen.</td></tr><tr><td><strong>LELSText</strong>=</td><td>Überschrift für den Leistungsstand. Das Feld kann wie im Standard auch leer bleiben.</td></tr><tr><td><strong>;WiderspruchInEingangsphaseAusblenden</strong></td><td>Per Standard ist der Widerspruchtstext für die Schuleingangsphase <em>nicht</em> ausgeblendet, wird also angezeigt. Ein Entfernen des Semikolons führt somit dazu, dass der Widerspruchstext nicht angezeigt wird.</td></tr><tr><td><strong>;Folgejahrgang</strong></td><td>Steuert, ob bei einer &quot;Versetzung&quot; die <em>neue Klasse</em> oder der <em>neue Jahrgang</em> angezeigt wird. Wird der Schalter <em>Folgejahrgang</em> über das Semikolon <em>Deaktiviert</em> wird ein Klassentext erzeugt: Max wird in die <em>Klasse 03a</em> versetzt. Ist der Schalter aufgrund des entfernten Semikolons <em>Aktiviert</em>, wird ein Jahrgangstext erzeugt: Aktiviert =&gt; Max wird in den <em>Jahrgang 03</em> versetzt</td></tr><tr><td><strong>BemerkungText</strong>=Bemerkung</td><td>Sofern hier ein Eintrag vorgenommen wird, ist dies die Überschrift für weitere <em>fachbezogene Bemerkungen</em> (unterhalb der Kompetenzen)).</td></tr><tr><td><strong>;BemerkungLeerText</strong>=-keine-</td><td>Ist <em>keine</em> Bemerkung eingetragen, soll der folgende freie Text erscheinen. Wenn ein Text gesetzt wird, muss der Schalter auch noch durch das Entfernen des Semikolons aktiviert werden.</td></tr><tr><td><strong>;SchulbesuchsjahrText</strong>=Schuleingangsphase $JAHR$. Schulbesuchsjahr</td><td>Der Text für Schulbesuchsjahre im Zeugniskopf kann bei bei Bedarf angepasst werden. Sofern ein Text gesetzt wird, ist der ganze Eintrag zusätzlich durch Entfernen des Semikolons zu aktivieren.</td></tr></tbody></table><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Grundschulzeugnisse_Konfiguration_des_Erscheinungsbildes_von_Zeugnissen_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6798.</p>',20)])])}const k=r(g,[["render",o]]);export{z as __pageData,k as default};
